-- =====================================================================
-- RipassoAI — 0008: 30 domande per Express e per Prisma
--   Express: 3 già presenti + 27 nuove
--   Prisma:  3 già presenti + 27 nuove
-- =====================================================================

select public.importa_quiz('express', $j$[
  {"livello":"L1","testo":"Come si crea un'applicazione Express?","spiegazione":"Si importa express e si chiama la funzione: const app = express().","opzioni":["const app = express()","const app = new Express()","const app = createServer()","const app = require('app')"],"corretta":0},
  {"livello":"L1","testo":"Quale metodo definisce una rotta GET?","spiegazione":"app.get('/percorso', handler) risponde alle richieste GET su quel percorso.","opzioni":["app.get","app.route","app.use","app.fetch"],"corretta":0},
  {"livello":"L1","testo":"Cosa sono i middleware?","spiegazione":"Funzioni che ricevono req, res e next e possono modificare la richiesta o terminare la risposta.","opzioni":["Funzioni con req, res e next","Plugin del database","File di configurazione","Template HTML"],"corretta":0},
  {"livello":"L1","testo":"Quale parametro passa il controllo al middleware successivo?","spiegazione":"next() prosegue nella catena; next(err) salta all'error handler.","opzioni":["next","res","req","done"],"corretta":0},
  {"livello":"L1","testo":"Dove si leggono i parametri di percorso come /utenti/:id?","spiegazione":"req.params contiene i valori dei segmenti dinamici della rotta.","opzioni":["req.params","req.query","req.body","req.headers"],"corretta":0},
  {"livello":"L1","testo":"Dove si leggono i parametri dopo il punto interrogativo?","spiegazione":"req.query contiene la query string già interpretata come oggetto.","opzioni":["req.query","req.params","req.body","req.url"],"corretta":0},
  {"livello":"L1","testo":"Dove si legge il body JSON di una richiesta?","spiegazione":"req.body, disponibile dopo il middleware express.json().","opzioni":["req.body","req.data","req.json","req.payload"],"corretta":0},
  {"livello":"L1","testo":"Come si invia una risposta in JSON?","spiegazione":"res.json(oggetto) imposta il content-type e serializza il valore.","opzioni":["res.json(oggetto)","res.sendJson(oggetto)","res.write(oggetto)","res.body(oggetto)"],"corretta":0},

  {"livello":"L2","testo":"Cosa fa express.json()?","spiegazione":"Interpreta il body con content-type JSON e lo mette in req.body.","opzioni":["Interpreta il body JSON in req.body","Comprime la risposta","Valida lo schema","Abilita il CORS"],"corretta":0},
  {"livello":"L2","testo":"Qual è la differenza tra app.use e app.get?","spiegazione":"use intercetta ogni metodo e prefisso, get solo le richieste GET su un percorso.","opzioni":["use vale per ogni metodo, get solo per GET","get vale per ogni metodo, use solo per GET","Sono equivalenti","use vale solo per gli errori"],"corretta":0},
  {"livello":"L2","testo":"Come si monta un router su un prefisso?","spiegazione":"app.use('/api', router) fa partire le rotte del router sotto /api.","opzioni":["app.use('/api', router)","app.get('/api', router)","app.mount('/api', router)","app.router('/api')"],"corretta":0},
  {"livello":"L2","testo":"Quale firma identifica un error handler Express?","spiegazione":"Deve avere quattro argomenti: err, req, res, next.","opzioni":["(err, req, res, next)","(req, res)","(err, next)","(req, res, err)"],"corretta":0},
  {"livello":"L2","testo":"Cosa fa res.status(404)?","spiegazione":"Imposta il codice di stato; la risposta va comunque inviata con send o json.","opzioni":["Imposta il codice di stato della risposta","Termina la richiesta","Lancia un errore","Reindirizza"],"corretta":0},
  {"livello":"L2","testo":"Cosa fa next(err)?","spiegazione":"Passa l'errore all'error handler centrale saltando i middleware normali.","opzioni":["Passa l'errore all'error handler","Riprova la richiesta","Ignora l'errore","Chiude la connessione"],"corretta":0},
  {"livello":"L2","testo":"Dove vanno i middleware di parsing?","spiegazione":"Prima delle rotte, altrimenti req.body non è disponibile negli handler.","opzioni":["Prima delle rotte","Dopo l'error handler","Dentro ogni handler","Solo nei test"],"corretta":0},
  {"livello":"L2","testo":"Cosa fa helmet()?","spiegazione":"Imposta header di sicurezza come CSP e X-Content-Type-Options.","opzioni":["Imposta header di sicurezza","Comprime le risposte","Registra le richieste","Gestisce le sessioni"],"corretta":0},

  {"livello":"L3","testo":"Perché l'ordine dei middleware è importante?","spiegazione":"Express li esegue in sequenza: un middleware dopo una risposta non viene eseguito.","opzioni":["Perché vengono eseguiti in sequenza e uno può terminare la catena","Perché l'ordine è casuale","Perché solo l'ultimo viene eseguito","Perché i router ignorano l'ordine"],"corretta":0},
  {"livello":"L3","testo":"Perché l'error handler va registrato per ultimo?","spiegazione":"Express lo riconosce dai quattro argomenti e lo usa solo per gli errori successivi nella catena.","opzioni":["Perché intercetta gli errori dei middleware precedenti","Perché deve essere la prima rotta","Perché altrimenti non compila","Perché usa il metodo GET"],"corretta":0},
  {"livello":"L3","testo":"Perché non inserire dettagli interni nei messaggi di errore?","spiegazione":"Stack trace e query rivelano informazioni utili a un attaccante: al client va un messaggio generico.","opzioni":["Rivelano informazioni utili a un attaccante","Rendono la risposta più lenta","Non sono compatibili con JSON","Aumentano i token JWT"],"corretta":0},
  {"livello":"L3","testo":"Perché 401 e 403 vanno distinti?","spiegazione":"401 significa identità assente o non valida, 403 identità valida ma permesso mancante.","opzioni":["401 è autenticazione mancante, 403 autorizzazione negata","Sono sinonimi","401 è per gli admin","403 è per gli ospiti"],"corretta":0},
  {"livello":"L3","testo":"Perché validare con uno schema come Zod?","spiegazione":"Un unico schema controlla tipi e campi, produce messaggi coerenti e può essere riusato lato client.","opzioni":["Un unico schema definisce tipi e messaggi coerenti","Sostituisce il database","Cripta il body","Genera il CSS"],"corretta":0},
  {"livello":"L3","testo":"Perché usare cookie httpOnly per la sessione?","spiegazione":"JavaScript non può leggerli, riducendo il furto di token tramite XSS.","opzioni":["JavaScript non può leggerli, riducendo il rischio XSS","Sono più veloci","Occupano meno spazio","Funzionano senza HTTPS"],"corretta":0},
  {"livello":"L3","testo":"Perché introdurre rate limiting sulle rotte di autenticazione?","spiegazione":"Limita tentativi ripetuti e rallenta brute force e abusi.","opzioni":["Limita brute force e abusi","Riduce i token JWT","Velocizza le query","Evita il CORS"],"corretta":0},

  {"livello":"L4","testo":"Perché il CORS non protegge l'API lato server?","spiegazione":"È applicato dal browser: un client HTTP diretto ignora il controllo e chiama comunque l'API.","opzioni":["È applicato dal browser e un client diretto lo ignora","Cripta solo le risposte","Funziona solo con HTTPS","Blocca le richieste server-to-server"],"corretta":0},
  {"livello":"L4","testo":"Perché controllare il ruolo non basta per autorizzare una risorsa?","spiegazione":"Serve anche l'ownership: un utente autenticato non deve leggere l'id altrui (IDOR).","opzioni":["Serve verificare anche che la risorsa appartenga all'utente","Il ruolo è sempre sufficiente","L'id è già cifrato","Il database filtra da solo"],"corretta":0},
  {"livello":"L4","testo":"Perché gli handler async possono sfuggire all'error handler in Express 4?","spiegazione":"Una Promise rifiutata non chiama next(err) da sola: serve un wrapper o Express 5.","opzioni":["Una Promise rifiutata non chiama next(err) da sola","Gli handler async non esistono","Express 4 usa solo callback","Il body non è disponibile"],"corretta":0},
  {"livello":"L4","testo":"Perché l'invio di un quiz va fatto in una transazione?","spiegazione":"Tentativo, risposte e aggiornamento della padronanza devono essere coerenti: o tutto o niente.","opzioni":["Per mantenere coerenti tentativo, risposte e padronanza","Per velocizzare la scrittura","Per evitare il CORS","Per comprimere il JSON"],"corretta":0}
]$j$::jsonb);

select public.importa_quiz('prisma', $j$[
  {"livello":"L1","testo":"Quale comando genera il client Prisma?","spiegazione":"prisma generate crea il client tipizzato a partire dallo schema.","opzioni":["prisma generate","prisma init","prisma db pull","prisma format"],"corretta":0},
  {"livello":"L1","testo":"In quale file si definisce il datasource?","spiegazione":"schema.prisma contiene datasource, generator e modelli.","opzioni":["schema.prisma","prisma.json","datasource.sql","client.prisma"],"corretta":0},
  {"livello":"L1","testo":"Quale metodo legge più righe?","spiegazione":"findMany restituisce un array e accetta where, select, orderBy e paginazione.","opzioni":["findMany","findUnique","findOne","getAll"],"corretta":0},
  {"livello":"L1","testo":"Quale metodo legge una riga tramite chiave univoca?","spiegazione":"findUnique accetta solo campi unique o chiavi composte.","opzioni":["findUnique","findFirst","findOne","query"],"corretta":0},
  {"livello":"L1","testo":"Quale metodo crea una riga?","spiegazione":"create inserisce un record e restituisce quello creato.","opzioni":["create","insert","add","save"],"corretta":0},
  {"livello":"L1","testo":"Quale comando applica le migrazioni in sviluppo?","spiegazione":"prisma migrate dev crea e applica la migrazione, poi rigenera il client.","opzioni":["prisma migrate dev","prisma db seed","prisma generate","prisma studio"],"corretta":0},
  {"livello":"L1","testo":"Dove si legge la stringa di connessione?","spiegazione":"env(\"DATABASE_URL\") nel datasource legge la variabile d'ambiente.","opzioni":["env(\"DATABASE_URL\")","config(\"DB\")","process.env","secret(\"DB\")"],"corretta":0},
  {"livello":"L1","testo":"Quale metodo aggiorna una riga?","spiegazione":"update richiede un where univoco e i dati da modificare.","opzioni":["update","set","patch","modify"],"corretta":0},

  {"livello":"L2","testo":"Qual è la differenza tra findUnique e findFirst?","spiegazione":"findUnique richiede un campo unique, findFirst accetta qualsiasi filtro e restituisce la prima riga.","opzioni":["findUnique richiede un campo unique, findFirst no","Sono identici","findFirst richiede un campo unique","findUnique restituisce un array"],"corretta":0},
  {"livello":"L2","testo":"Cosa fa include?","spiegazione":"Carica le relazioni collegate nella stessa query, restituendole annidate.","opzioni":["Carica le relazioni collegate","Filtra i campi","Ordina i risultati","Crea un indice"],"corretta":0},
  {"livello":"L2","testo":"Cosa fa select?","spiegazione":"Sceglie solo i campi indicati, riducendo il payload restituito.","opzioni":["Sceglie i campi da restituire","Seleziona la tabella","Crea una vista","Esegue una join manuale"],"corretta":0},
  {"livello":"L2","testo":"Cosa fa where?","spiegazione":"Applica i filtri in stile oggetto, componibili con AND e OR.","opzioni":["Applica i filtri","Ordina i risultati","Limita le righe","Seleziona i campi"],"corretta":0},
  {"livello":"L2","testo":"Cosa fa orderBy?","spiegazione":"Ordina per uno o più campi, con direzione asc o desc.","opzioni":["Ordina i risultati","Filtra i risultati","Raggruppa i risultati","Unisce le tabelle"],"corretta":0},
  {"livello":"L2","testo":"Cosa fa prisma migrate deploy?","spiegazione":"Applica le migrazioni pendenti in un ambiente esistente, tipicamente produzione.","opzioni":["Applica le migrazioni pendenti in produzione","Crea un nuovo schema","Genera dati demo","Apre Prisma Studio"],"corretta":0},
  {"livello":"L2","testo":"Cosa definisce @relation?","spiegazione":"Descrive la relazione tra due modelli e i campi di chiave esterna.","opzioni":["La relazione tra due modelli","Un indice","Un vincolo di unicità","Un valore di default"],"corretta":0},
  {"livello":"L2","testo":"Come si pagina una query con Prisma?","spiegazione":"Con take (quante righe) e skip (quante saltarne).","opzioni":["take e skip","limit e offset","page e size","first e last"],"corretta":0},

  {"livello":"L3","testo":"Perché preferire select a restituire tutti i campi?","spiegazione":"Riduce il payload e permette query più leggere, evitando di esporre campi sensibili.","opzioni":["Riduce il payload ed evita di esporre campi sensibili","Rende il codice più lungo","Impedisce le relazioni","Disattiva gli indici"],"corretta":0},
  {"livello":"L3","testo":"Perché una transazione interattiva ha un timeout?","spiegazione":"Evita che una transazione bloccata mantenga lock e connessioni a tempo indefinito.","opzioni":["Evita lock e connessioni bloccati all'infinito","Per limitare i token","Per chiudere il client","Per comprimere i dati"],"corretta":0},
  {"livello":"L3","testo":"Perché upsert è utile negli import?","spiegazione":"Crea o aggiorna in base alla chiave, rendendo l'operazione idempotente.","opzioni":["Crea o aggiorna in base alla chiave, in modo idempotente","Elimina i duplicati","Crea un indice","Esegue una join"],"corretta":0},
  {"livello":"L3","testo":"Perché usare un vincolo unique su più colonne?","spiegazione":"Impedisce duplicati logici, come la stessa iscrizione a corso e utente.","opzioni":["Impedisce duplicati logici su più colonne","Velocizza le letture","Crea una chiave esterna","Ordina la tabella"],"corretta":0},
  {"livello":"L3","testo":"Perché diffidare di deleteMany senza where?","spiegazione":"Senza filtro cancella tutte le righe della tabella.","opzioni":["Senza filtro cancella tutte le righe","Elimina solo l'ultima","Lancia sempre errore","Crea un backup automatico"],"corretta":0},
  {"livello":"L3","testo":"Perché i tipi generati da Prisma aiutano?","spiegazione":"Il compilatore segnala campi e argomenti errati prima dell'esecuzione.","opzioni":["Segnalano errori di campi e argomenti a compile time","Velocizzano il database","Generano il CSS","Criptano le query"],"corretta":0},
  {"livello":"L3","testo":"Perché usare createMany per gli import massivi?","spiegazione":"Esegue un solo round trip invece di una query per riga.","opzioni":["Riduce le query a un solo round trip","Crea relazioni automatiche","Valida lo schema","Genera indici"],"corretta":0},

  {"livello":"L4","testo":"Perché il problema N+1 nasce dalle query dentro un ciclo?","spiegazione":"Una query per la lista e una per ogni elemento: si risolve con include o con una query unica.","opzioni":["Si esegue una query per ogni elemento della lista","Il database rifiuta le join","Il client non supporta gli array","Manca la chiave primaria"],"corretta":0},
  {"livello":"L4","testo":"Perché non concatenare input utente in una query raw?","spiegazione":"Apre a SQL injection: Prisma.sql e i parametri vanno sempre usati per i valori.","opzioni":["Apre a SQL injection: servono query parametrizzate","È più lento","Non supporta i join","Richiede permessi admin"],"corretta":0},
  {"livello":"L4","testo":"Perché il connection pooling è critico in ambiente serverless?","spiegazione":"Ogni istanza apre connessioni: senza pooling si esauriscono i limiti del database.","opzioni":["Ogni istanza apre connessioni e si esaurisce il limite del database","Le funzioni non supportano TCP","Prisma non funziona in serverless","Il pool cancella i dati"],"corretta":0},
  {"livello":"L4","testo":"Perché una transazione non dovrebbe attendere chiamate esterne?","spiegazione":"I lock restano aperti fino alla risposta: meglio commit brevi e operazioni idempotenti.","opzioni":["I lock restano aperti fino alla risposta esterna","Il database non supporta HTTP","Prisma chiude la connessione","Le transazioni non hanno timeout"],"corretta":0}
]$j$::jsonb);
